    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Missing required `challenge` field.",
                "{\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\"\n}",
            ),
            (
                "Missing required `sessionId` field.",
                "{\n  \"challenge\": \"ZGN3RvOXh0c3JydWxsbmJzcmVxdHJjQVZjbA\"\n}",
            ),
            (
                "Challenge too short — schema enforces ≥16 chars (the wire form of a 128-bit nonce in base64url is ≥22 chars; the floor here is liberal to allow padded encodings).",
                "{\n  \"challenge\": \"short\",\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\"\n}",
            ),
            (
                "Unknown top-level payload member.",
                "{\n  \"challenge\": \"ZGN3RvOXh0c3JydWxsbmJzcmVxdHJjQVZjbA\",\n  \"frobnicate\": true,\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\"\n}",
            ),
            (
                "sessionKey is not a did:key VID — the schema requires the did:key method specifically (bare multikey or another DID method is rejected), for consistency with the passkey path's did:key session-key store.",
                "{\n  \"challenge\": \"ZGN3RvOXh0c3JydWxsbmJzcmVxdHJjQVZjbA\",\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\",\n  \"sessionKey\": \"did:web:alice.example#session-1\"\n}",
            ),
            (
                "sessionKey carrying a bare multikey instead of a did:key VID — the schema requires the did:key: prefix, not the raw multibase-encoded key alone.",
                "{\n  \"challenge\": \"ZGN3RvOXh0c3JydWxsbmJzcmVxdHJjQVZjbA\",\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\",\n  \"sessionKey\": \"z6MkpTHR8VNsBxYAAWHut2Geadd9jSwuBV8xRoAnwWsdvktH\"\n}",
            ),
            (
                "principal is not a DID (`did:` prefix required) — a bare handle is not a VID the delegation machinery can reason about.",
                "{\n  \"challenge\": \"ZGN3RvOXh0c3JydWxsbmJzcmVxdHJjQVZjbA\",\n  \"principal\": \"alice.example\",\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\"\n}",
            ),
            (
                "delegationEvidence missing required `kind` — the consumer's policy has no vocabulary to evaluate an evidence object that doesn't say what class it is, so `kind` is REQUIRED whenever the member is present at all.",
                "{\n  \"challenge\": \"ZGN3RvOXh0c3JydWxsbmJzcmVxdHJjQVZjbA\",\n  \"delegationEvidence\": {\n    \"reference\": \"vta-context:personal/console\"\n  },\n  \"principal\": \"did:web:alice.example\",\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\"\n}",
            ),
            (
                "delegationEvidence carrying an unknown member — additionalProperties: false catches a producer inventing its own field instead of using `kind`/`credential`/`reference`/`ext`.",
                "{\n  \"challenge\": \"ZGN3RvOXh0c3JydWxsbmJzcmVxdHJjQVZjbA\",\n  \"delegationEvidence\": {\n    \"kind\": \"vtaContext\",\n    \"trustMe\": true\n  },\n  \"principal\": \"did:web:alice.example\",\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
